<ul>
  <li *ngFor="let node of nodes">
    {{ node.name }}
    <ul [hidden]="!node.children.length">
      <tree-node *ngFor="let child of node.children" [nodes]="child"></tree-node>
    </ul>
  </li>
</ul>
```

### 3. **Add Drag & Drop Support (Optional)**

To add drag-and-drop functionality, you might need to implement custom logic for dragging and dropping nodes between lists.

#### Example: Using Custom Drag & Drop Directive

Create a directive to handle the drag-and-drop behavior:

```typescript
// draggable.directive.ts
import { Directive, Input, Output, EventEmitter, HostListener } from '@angular/core';
import { TreeNode } from '../node/node.component'; // Adjust path based on actual import location

@Directive({ selector: '[appDraggable]' })
export class DraggableDirective {
  @Input() appDraggable: boolean;
  @Output() dragStartEvent = new EventEmitter<void>();
  @Output() dropEvent = new EventEmitter<TreeNode>();

  @HostListener('dragstart', ['$event'])
  startDragging(event) {
    event.dataTransfer.setData('text/plain', '');
    this.dragStartEvent.emit();
  }

  @HostListener('drop')
  handleDrop(event) {
    const data = event.dataTransfer.getData('text/plain');
    if (data !== '') {
      let targetNode = null;
      this.nodes.forEach(node => {
        if (node.id === parseInt(data)) {
          targetNode = node;
        }
      });
      if (targetNode && targetNode.children) {
        targetNode.children.push(...this.nodes);
        this.nodes.forEach(node => {
          node.parent = targetNode;
        });
      }
      this.dropEvent.emit(targetNode);
    }
  }

  @HostListener('dragover', ['$event'])
  handleDragOver(event) {
    event.preventDefault();
  }

  @HostListener('dragend', ['$event'])
  handleDragEnd(event) {
    this.dragStartEvent.emit();
  }
}
```

